(4, 'The Ultimate Guide to Real Estate Investment in 2023', 'blog/1748941093_photo-1605146769289-440113cc3d00.jpg', '<section style=\"padding: 0px; margin: 0px 0px 30px; border: 0px; outline: none; list-style: none; text-size-adjust: none; appearance: none; float: left; width: 1905px; color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, sans-serif; font-size: 10px;\"><div class=\"container\" style=\"padding: 0px 20px; margin-top: 0px; margin-bottom: 0px; border: 0px; outline: none; list-style: none; text-size-adjust: none; appearance: none; max-width: 1044px; width: 1044px;\"><div class=\"blogPostContainerDescription\" style=\"padding: 0px 30px 0px 0px; margin: 0px; border: 0px; outline: none; list-style: none; text-size-adjust: none; appearance: none; float: left; width: 702.797px;\"><div style=\"padding: 0px; margin: 0px; border: 0px; outline: none; list-style: none; text-size-adjust: none; appearance: none;\"><div class=\"loc article-pre-content\" style=\"grid-area: pre-content; color: rgb(17, 17, 17); font-family: SourceSansPro, &quot;Source Sans Pro-fallback&quot;, sans-serif; font-size: 18px; letter-spacing: 0.05px;\"><header id=\"article-header_1-0\" class=\"comp article-header mntl-block right-rail__offset js-toc-appear\" style=\"grid-area: header;\"><h1 id=\"article-heading_1-0\" class=\"comp article-heading mntl-text-block\" style=\"box-sizing: border-box; margin: 0px 0px 1rem; font-family: Cabin-semi-bold, Cabin-fallback, sans-serif; font-size: 48px; font-weight: 600; line-height: 1.1;\">5 Simple Ways to Invest in Real Estate</h1><h1 id=\"article-heading_1-0\" class=\"comp article-heading mntl-text-block\" style=\"margin-right: 0px; margin-bottom: 1rem; margin-left: 0px; font-family: Cabin-semi-bold, Cabin-fallback, sans-serif; font-size: 48px; font-weight: 600; line-height: 1.1;\"><div class=\"loc article-pre-content\" style=\"font-weight: 400; grid-area: pre-content; font-family: SourceSansPro, &quot;Source Sans Pro-fallback&quot;, sans-serif; font-