--
-- Table structure for table `full_property_schema`
--

CREATE TABLE `full_property_schema` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `rera_id` varchar(255) DEFAULT NULL,
  `slug` varchar(255) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `description` longtext NOT NULL,
  `property_type` enum('Apartment','Villa','Residential Plot','Commercial','Penthouse','House','Condo','Townhouse','Residential Flat') NOT NULL,
  `listing_type` enum('For Rent','For Sale','Lease','For Resale') NOT NULL,
  `price` text DEFAULT NULL,
  `price_unit` varchar(255) DEFAULT NULL,
  `security_deposit` decimal(12,2) DEFAULT NULL,
  `property_id` varchar(255) DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `city` varchar(255) DEFAULT NULL,
  `state` varchar(255) DEFAULT NULL,
  `country` varchar(255) NOT NULL DEFAULT 'India',
  `zip_code` varchar(255) DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `landmark` text DEFAULT NULL,
  `google_map_link` varchar(255) DEFAULT NULL,
  `bazar_distance_km` text DEFAULT NULL,
  `hospital_distance_km` text DEFAULT NULL,
  `school_distance_km` text DEFAULT NULL,
  `bus_stand_distance_km` text DEFAULT NULL,
  `junction_distance_km` text DEFAULT NULL,
  `airport_distance_km` text DEFAULT NULL,
  `bedrooms` int(11) DEFAULT NULL,
  `bathrooms` int(11) DEFAULT NULL,
  `balconies` int(11) DEFAULT NULL,
  `floors` int(11) DEFAULT NULL,
  `floor_number` int(11) DEFAULT NULL,
  `super_area` decimal(10,2) DEFAULT NULL,
  `carpet_area` decimal(10,2) DEFAULT NULL,
  `plot_area` decimal(10,2) DEFAULT NULL,
  `year_built` int(11) DEFAULT NULL,
  `age_of_property` int(11) DEFAULT NULL,
  `furnishing` enum('Fully Furnished','Semi Furnished','Unfurnished') DEFAULT NULL,
  `furnishing_details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`furnishing_details`)),
  `features` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`features`)),
  `amenities` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`amenities`)),
  `availability` enum('Immediate','After Date','Negotiable') NOT NULL DEFAULT 'Immediate',
  `available_from` date DEFAULT NULL,
  `preferred_tenants` enum('Family','Professionals','Students','Company','Anyone') DEFAULT NULL,
  `main_image` varchar(255) DEFAULT NULL,
  `video_url` varchar(255) DEFAULT NULL,
  `floor_plan_image` varchar(255) DEFAULT NULL,
  `brochure` varchar(255) DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `pre_launch_property` tinyint(1) DEFAULT 0,
  `is_verified` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `property_status` enum('Available','Rented','Sold','Under Maintenance') NOT NULL DEFAULT 'Available',
  `notes` text DEFAULT NULL,
  `keyfeatures` text DEFAULT NULL,
  `user_id` bigint(20) UNSIGNED NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `full_property_schema`
--

INSERT INTO `full_property_schema` (`id`, `rera_id`, `slug`, `title`, `description`, `property_type`, `listing_type`, `price`, `price_unit`, `security_deposit`, `property_id`, `location`, `address`, `city`, `state`, `country`, `zip_code`, `latitude`, `longitude`, `landmark`, `google_map_link`, `bazar_distance_km`, `hospital_distance_km`, `school_distance_km`, `bus_stand_distance_km`, `junction_distance_km`, `airport_distance_km`, `bedrooms`, `bathrooms`, `balconies`, `floors`, `floor_number`, `super_area`, `carpet_area`, `plot_area`, `year_built`, `age_of_property`, `furnishing`, `furnishing_details`, `features`, `amenities`, `availability`, `available_from`, `preferred_tenants`, `main_image`, `video_url`, `floor_plan_image`, `brochure`, `is_featured`, `pre_launch_property`, `is_verified`, `is_active`, `property_status`, `notes`, `keyfeatures`, `user_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
